fn decode_cyclic(s: &Vec<i8>) -> Vec<i8> {
    let l = s.len();
    let p = l - (l % 3);
    let mut res = Vec::with_capacity(l);

    for i in 0..p {
        match i % 3 {
            0 => res.push(s[i + 2]),
            1 => res.push(s[i - 1]),
            2 => res.push(s[i]),  // For i mod 3 == 2, no transformation specified, so keep input.
            _ => unreachable!(),
        }
    }

    // Append remaining elements unchanged
    for i in p..l {
        res.push(s[i]);
    }

    res
}